<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_admin();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$p=['nome'=>'','descricao'=>'','preco'=>'','estoque'=>0,'categoria_id'=>'','imagem'=>'','ativo'=>1];if($id){$s=db()->prepare("SELECT * FROM produtos WHERE id=?");$s->execute([$id]);$p=$s->fetch()?:$p;}
$cats=db()->query("SELECT id,nome FROM categorias ORDER BY nome")->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$data=[trim($_POST['nome']??''),trim($_POST['descricao']??''),(float)($_POST['preco']??0),(int)($_POST['estoque']??0),(int)($_POST['categoria_id']??0),trim($_POST['imagem']??''),(int)isset($_POST['ativo'])];if($data[0]===''||$data[2]<0||$data[3]<0||$data[4]<1)$error='Preencha os campos corretamente.';else{if($id){$s=db()->prepare("UPDATE produtos SET nome=?,descricao=?,preco=?,estoque=?,categoria_id=?,imagem=?,ativo=? WHERE id=?");$s->execute([...$data,$id]);}else{$s=db()->prepare("INSERT INTO produtos (nome,descricao,preco,estoque,categoria_id,imagem,ativo) VALUES (?,?,?,?,?,?,?)");$s->execute($data);}header('Location: produtos.php');exit;}}
$pageTitle=$id?'Editar produto':'Novo produto';require dirname(__DIR__).'/includes/header.php';?>
<h1 class="h2 mb-4"><?= e($pageTitle) ?></h1><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><div class="card"><div class="card-body"><form method="post"><?= csrf_field() ?><div class="mb-3"><label class="form-label">Nome</label><input class="form-control" name="nome" required value="<?= e($p['nome']) ?>"></div><div class="mb-3"><label class="form-label">Descrição</label><textarea class="form-control" name="descricao" rows="4"><?= e($p['descricao']) ?></textarea></div><div class="row"><div class="col-md-4 mb-3"><label class="form-label">Preço (R$)</label><input class="form-control" type="number" min="0" step=".01" name="preco" required value="<?= e($p['preco']) ?>"></div><div class="col-md-4 mb-3"><label class="form-label">Estoque</label><input class="form-control" type="number" min="0" name="estoque" required value="<?= e($p['estoque']) ?>"></div><div class="col-md-4 mb-3"><label class="form-label">Categoria</label><select class="form-select" name="categoria_id" required><?php foreach($cats as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)$p['categoria_id']===(int)$c['id']?'selected':'' ?>><?= e($c['nome']) ?></option><?php endforeach; ?></select></div></div><div class="mb-3"><label class="form-label">Caminho ou URL da imagem</label><input class="form-control" name="imagem" value="<?= e($p['imagem']) ?>" placeholder="assets/img/placeholder.svg"></div><div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="ativo" id="ativo" <?= $p['ativo']?'checked':'' ?>><label class="form-check-label" for="ativo">Produto ativo</label></div><button class="btn btn-dark">Salvar</button> <a href="produtos.php" class="btn btn-outline-secondary">Cancelar</a></form></div></div>
